// with_named_comments loads `comments` as `configure` says into
// `named_comments[name]`, besides any other load of it.
pub fn (q ArticleQuery) with_named_comments(name string, configure ...fn (CommentQuery) CommentQuery) ArticleQuery {
	mut next := q
	mut named := q.named_comments.clone()
	named[name] = configure
	next.named_comments = named
	return next
}

// with_author loads each row's `author` (many_to_one `users`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q ArticleQuery) with_author(configure ...fn (UserQuery) UserQuery) ArticleQuery {
	mut next := q
	next.with_author = true
	next.author_fns = configure
	return next
}

// with_comments loads each row's `comments` (one_to_many `comments`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q ArticleQuery) with_comments(configure ...fn (CommentQuery) CommentQuery) ArticleQuery {
	mut next := q
	next.with_comments = true
	next.comments_fns = configure
	return next
}

// all returns the matching rows, with the requested edges.
pub fn (q ArticleQuery) all() ![]ArticleNode {
	rows := load.select_where[articles_models.Article](q.graph.client.conn, q.graph.client.prepare_query('articles', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q ArticleQuery) first() !ArticleNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'articles'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q ArticleQuery) nodes(rows []articles_models.Article) ![]ArticleNode {
	mut nodes := rows.map(ArticleNode{
		graph:   q.graph
		article: it
	})
	if q.with_author {
		found := q.load_author(rows, q.author_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.article.id.str()] or { [] }
			if list.len > 0 {
				node.author = &UserNode{
					...list[0]
				}
			}
			node.loaded << 'author'
		}
	}
	if q.with_comments {
		found := q.load_comments(rows, q.comments_fns)!
		for mut node in nodes {
			node.comments = found[node.article.id.str()] or { [] }
			node.loaded << 'comments'
		}
	}
	for name, fns in q.named_comments {
		found := q.load_comments(rows, fns)!
		for mut node in nodes {
			node.named_comments[name] = found[node.article.id.str()] or { [] }
		}
	}
	return nodes
}

// load_author loads the `author` of `rows`, keyed by each row's key.
fn (q ArticleQuery) load_author(rows []articles_models.Article, fns []fn (UserQuery) UserQuery) !map[string][]UserNode {
	mut sub := q.graph.users()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		keys << row.user_id.str()
	}
	targets := sub.nodes(load.select_in[users_models.User](q.graph.client.conn, 'id',
		load.unique(keys),
		query: q.graph.client.prepare_query('users', sub.query)!
	)!)!
	mut by_key := map[string]UserNode{}
	for target in targets {
		by_key[target.user.id.str()] = target
	}
	mut found := map[string][]UserNode{}
	for row in rows {
		if target := by_key[row.user_id.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// author_or_err returns the `author`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n ArticleNode) author_or_err() !&UserNode {
	if 'author' !in n.loaded {
		return NotLoadedError{
			edge: 'articles.author'
		}
	}
	if target := n.author {
		return target
	}
	return NotFoundError{
		table: 'users'
	}
}

// load_comments loads the `comments` of `rows`, keyed by each row's key.
fn (q ArticleQuery) load_comments(rows []articles_models.Article, fns []fn (CommentQuery) CommentQuery) !map[string][]CommentNode {
	mut sub := q.graph.comments()
	for configure in fns {
		sub = configure(sub)
	}
	children := sub.nodes(load.select_each[comments_models.Comment](q.graph.client.conn,
		'owner_id', rows.map(it.id.str()),
		type_col: 'owner_type'
		type_val: 'Article'
		soft_del: 'deleted_at'
		query:    q.graph.client.prepare_query('comments', sub.query)!
	)!)!
	mut by_parent := map[string][]CommentNode{}
	for child in children {
		by_parent[child.comment.owner_id.str()] << child
	}
	return by_parent
}

// comments_or_err returns the `comments`, or a `NotLoadedError` when the query
// didn't load them.
pub fn (n ArticleNode) comments_or_err() ![]CommentNode {
	if 'comments' !in n.loaded {
		return NotLoadedError{
			edge: 'articles.comments'
		}
	}
	return n.comments
}

// query_author starts a query of this row's `author`, which matches
// nothing when the row has none.
pub fn (n ArticleNode) query_author() UserQuery {
	key := n.article.user_id
	return n.graph.users().where(load.eq('id', key))
}

// query_comments starts a query of this row's `comments`.
pub fn (n ArticleNode) query_comments() CommentQuery {
	return n.graph.comments().where(load.eq('owner_id', n.article.id), load.eq('owner_type', 'Article'), load.is_null('deleted_at'))
}
